import numpy as np
e=np.asarray(df['eps']);T=np.asarray(df['T']);s=np.asarray(df['sigma'])
def tryb(K,M):
    cols=[];names=[]
    for k in range(1,K+1):
        for m in range(0,M+1):
            cols.append(e**k*T**m);names.append(f'e{k}T{m}')
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,s,rcond=None)[0]
    r=s-X@c
    return np.mean(r**2)/np.var(s), len(cols)
